// Register custom payload handler
public class MyMod {
    public static final ResourceLocation CUSTOM_PAYLOAD = 
        new ResourceLocation(MODID, "custom_payload");

    public void onCommonSetup(FMLCommonSetupEvent event) {
        // Register custom payload
        PayloadTypeRegistry.playC2S().register(CUSTOM_PAYLOAD, MyPayload.CODEC);

        // Register handler
        PlayPayloadRegistrationHandlerHandler.INVOKER.registerPlayPayloadS2CHandler(
            CUSTOM_PAYLOAD,
            (payload, context) -> {
                context.enqueueWork(() -> {
                    // Handle payload on main thread
                    handlePayload(payload, context.getPlayer());
                });
            }
        );
    }
}

// Listen for connection events
MinecraftForge.EVENT_BUS.addListener((NetworkEvent.CustomPayloadEvent event) -> {
    if (CUSTOM_PAYLOAD.equals(event.getPayload().id())) {
        // Handle custom payload
    }
});
